(()=>{const $=q=>document.querySelector(q),reduce=matchMedia('(prefers-reduced-motion: reduce)');let recording=true,voiceTimer;$('#record-toggle').onclick=()=>{recording=!recording;$('#record-state').textContent=recording?'Recording':'Saved';$('#record-wave').classList.toggle('paused',!recording);$('#record-toggle').setAttribute('aria-label',recording?'Pause recording demonstration':'Replay recording demonstration');$('#record-hint').textContent=recording?'Double-press to start / stop.':'Saved in Sessions.'};$('#highlight-toggle').onclick=()=>{const on=$('#highlight-toggle').getAttribute('aria-pressed')!=='true';$('#highlight-toggle').setAttribute('aria-pressed',String(on));$('#highlight-toggle').textContent=on?'Highlighted':'Highlight';$('#highlight-quote').classList.toggle('unmarked',!on)};document.querySelectorAll('[data-context-view]').forEach(b=>b.onclick=()=>{document.querySelectorAll('[data-context-view]').forEach(x=>x.setAttribute('aria-selected',String(x===b)));$('#context-list').hidden=b.dataset.contextView!=='0';$('#actions-list').hidden=b.dataset.contextView!=='1'});$('#voice-play').onclick=()=>{clearTimeout(voiceTimer);$('.app-voice-prototype').classList.add('playing');$('#voice-state').textContent='Listening…';voiceTimer=setTimeout(()=>{$('.app-voice-prototype').classList.remove('playing');$('#voice-state').textContent='Voice command received.'},reduce.matches?0:1800)};const dialog=$('#cinema-review-dialog');$('#cinema-review').onclick=()=>dialog.showModal();$('#cinema-close').onclick=()=>dialog.close();$('#cinema-send').onclick=()=>{$('.app-confirm-actions').hidden=true;$('#cinema-sent').hidden=false;$('#annotation-title').textContent='SENT TO MAYA';$('#annotation-detail').textContent='Slack message delivered.'}})();
